import{_ as t,o as a,c as o,a2 as s}from"./chunks/framework.CpZKh-tG.js";const g=JSON.parse('{"title":"Slice A v3 — manual-source backlog","description":"","frontmatter":{},"headers":[],"relativePath":"provenance/slice-a-v3-manual-source-backlog.md","filePath":"provenance/slice-a-v3-manual-source-backlog.md"}'),d={name:"provenance/slice-a-v3-manual-source-backlog.md"};function r(l,e,i,c,n,h){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="slice-a-v3-—-manual-source-backlog" tabindex="-1">Slice A v3 — manual-source backlog <a class="header-anchor" href="#slice-a-v3-—-manual-source-backlog" aria-label="Permalink to &quot;Slice A v3 — manual-source backlog&quot;">​</a></h1><p>Generated 2026-06-18 after Slice A v3 round-4 ship.</p><h2 id="why-this-list-exists" tabindex="-1">Why this list exists <a class="header-anchor" href="#why-this-list-exists" aria-label="Permalink to &quot;Why this list exists&quot;">​</a></h2><p>During Marko&#39;s round-4 manual rescue pass, several gallery slots were &quot;approved&quot; not because the proposed image was a true hero — but because the auto-pipeline had nothing better. The dropped-pool alternatives for these slots were random off-topic content (cars, horses, houses, trees, etc., surfaced via fuzzy NASA Images query matches). Marko picked the duplicate-of-another-slot as the <strong>least-bad</strong> option so the gallery isn&#39;t blank on the live site, with the explicit understanding that these slots need hand-sourcing later.</p><p>The underlying cause: the <code>slice-a-*-dryrun.json</code> files were generated <strong>before</strong> commit <code>20f3016ac</code> (Stage 2 — resolver per-pick dedup across dry-run). Inside a single dryrun the resolver returned the same top-1 candidate for every slot of a given mission. The next pipeline iteration regenerates the dry-runs through the diversified resolver, which will give multi-slot missions a fighting chance at distinct candidates — but until then, the slots listed below are knowingly populated with duplicates.</p><p>The allowlists are in <code>scripts/validate-image-dupes.ts</code> under the <code>ALLOWLIST_AUTHORIZED (2026-06-18) — Slice A v3 round-4 rescue ship</code> comment block. Removing entries from there once the slots have proper hand-sourced replacements lands as part of the cleanup.</p><h2 id="items-needing-hand-sourcing" tabindex="-1">Items needing hand-sourcing <a class="header-anchor" href="#items-needing-hand-sourcing" aria-label="Permalink to &quot;Items needing hand-sourcing&quot;">​</a></h2><h3 id="fleet-galleries-gallery-slots-filled-with-duplicate-of-hero" tabindex="-1">Fleet galleries (gallery slots filled with duplicate of hero) <a class="header-anchor" href="#fleet-galleries-gallery-slots-filled-with-duplicate-of-hero" aria-label="Permalink to &quot;Fleet galleries (gallery slots filled with duplicate of hero)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Mission</th><th>Slots</th><th>Same byte SHA</th><th>Rationale</th></tr></thead><tbody><tr><td><code>a7l</code> (A7L spacesuit)</td><td>03, 04, 05</td><td><code>eada8e1c</code></td><td>Suit lineage gallery; 3 slots show the same suit photo</td></tr><tr><td><code>aces</code> (ACES launch/entry suit)</td><td>02, 03, 04, 05</td><td><code>702fcc41</code></td><td>All 4 gallery slots collapsed to one image</td></tr><tr><td><code>cygnus-standard</code></td><td>02, 03, 05</td><td><code>78248fa6</code></td><td>Cygnus cargo fleet gallery; 3 slots same image</td></tr><tr><td><code>emu</code> (Extravehicular Mobility Unit)</td><td>02, 03, 04, 05</td><td><code>0028195c</code></td><td>EVA suit gallery; all 4 slots one image</td></tr><tr><td><code>lc-34</code> (Launch Complex 34)</td><td>03, 04, 05</td><td><code>7dacaa15</code></td><td>Apollo-era pad; gallery shows same pad shot 3×</td></tr><tr><td><code>lunar-prospector</code></td><td>01, 04</td><td><code>5671243e</code></td><td>Hero AND gallery slot 04 are the same image</td></tr><tr><td><code>maven</code></td><td>01, 04</td><td><code>d79e07ae</code></td><td>Hero AND gallery slot 04 are the same image</td></tr></tbody></table><h3 id="mission-galleries-hero-gallery-slot-duplicate" tabindex="-1">Mission galleries (hero + gallery slot duplicate) <a class="header-anchor" href="#mission-galleries-hero-gallery-slot-duplicate" aria-label="Permalink to &quot;Mission galleries (hero + gallery slot duplicate)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Mission</th><th>Slots</th><th>Same byte SHA</th><th>Rationale</th></tr></thead><tbody><tr><td><code>dart</code></td><td>01, 05</td><td><code>12042c1f</code></td><td>DART hero + slot 05 share the same image</td></tr><tr><td><code>freedom-7</code></td><td>03, 05</td><td><code>730db1bd</code></td><td>Two gallery slots show same image</td></tr><tr><td><code>friendship-7</code></td><td>01, 02</td><td><code>5faf9c60</code></td><td>Hero + gallery slot 02 are the same image</td></tr><tr><td><code>mercury-atlas-9</code></td><td>03, 05</td><td><code>f2730ab6</code></td><td>Two gallery slots show same image</td></tr><tr><td><code>mercury-redstone-3</code></td><td>01, 04</td><td><code>de85aceb</code></td><td>Hero + gallery slot 04 are the same image</td></tr><tr><td><code>spirit</code></td><td>01, 02</td><td><code>ff4e464c</code></td><td>Hero + gallery slot 02 are the same image</td></tr></tbody></table><h2 id="suggested-hand-sourcing-priority" tabindex="-1">Suggested hand-sourcing priority <a class="header-anchor" href="#suggested-hand-sourcing-priority" aria-label="Permalink to &quot;Suggested hand-sourcing priority&quot;">​</a></h2><ol><li><strong>Hero+slot dupes</strong> (lunar-prospector, maven, dart, friendship-7, mercury-redstone-3, spirit) — these create a &quot;the hero is the same as one gallery slot&quot; visual repeat that&#39;s especially obvious on the site. Sourcing distinct slot images first removes the most visible collisions.</li><li><strong>Long galleries with single image</strong> (aces 02-05, emu 02-05) — these show &quot;1 image pretending to be 4&quot; which is the worst UX. Even 1 alternative per slot would help.</li><li><strong>Spacesuit gallery slots</strong> (a7l 03-05) — lower priority because the suit hardware is consistent across photos; less &quot;obvious copy&quot; feel.</li><li><strong>Pad/launch-site galleries</strong> (lc-34 03-05) — same shot from different angles is plausible; lower visual impact.</li></ol><h2 id="when-sourcing-replacements" tabindex="-1">When sourcing replacements <a class="header-anchor" href="#when-sourcing-replacements" aria-label="Permalink to &quot;When sourcing replacements&quot;">​</a></h2><p>For each slot above:</p><ol><li>Find a candidate image via the Wikimedia Commons / NASA Images / agency archive that&#39;s distinct from the existing slot 01 of that mission.</li><li>Drop the file at <code>static/images/&lt;surface&gt;/&lt;missionId&gt;/&lt;slot&gt;.jpg</code> replacing the duplicate.</li><li>Update the matching sidecar entry in <code>static/data/fleet-image-sources.json</code> or <code>static/data/mission-image-sources.json</code> with the new source metadata (<code>source_type</code>, <code>image_url</code>, <code>credit</code>, <code>license</code>).</li><li>Remove the corresponding SHA from <code>scripts/validate-image-dupes.ts</code> ALLOWLIST so the byte-dupe gate re-engages.</li><li>Re-run <code>npm run build-image-provenance</code> and the byte/phash validators to confirm clean.</li></ol><h2 id="counts" tabindex="-1">Counts <a class="header-anchor" href="#counts" aria-label="Permalink to &quot;Counts&quot;">​</a></h2><ul><li>Items in this backlog: <strong>13 dupe groups</strong> spanning <strong>33 image files</strong>.</li><li>Each group has 2–4 slots collapsed to a single image.</li><li>Total cleanup work: ~33 hand-sourced replacements + 13 allowlist entries to retire.</li></ul>',18)])])}const p=t(d,[["render",r]]);export{g as __pageData,p as default};
